use super::*;
pub(super) fn reference(owner:&Pubkey)->bool {
 let bytes=owner.to_bytes();
 let r=bytes==bpf_loader::id().to_bytes()||bytes==bpf_loader_upgradeable::id().to_bytes()||bytes==loader_v4::id().to_bytes();
 !r
}
#[kani::proof_for_contract(super::supported_loader)]
#[kani::unwind(33)]
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NFO_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NFO_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NFO_KMX::KMX_realloc)]
fn association(){let owner=Pubkey::new_from_array(kani::any());let actual=supported_loader(&owner);assert!(actual==reference(&owner));}
